mapper.select:
/* AdminMoim_SQL.selectAdminMoimLocateList */ SELECT LOCATE_ID , LOCATE_NM , LOCATE_POST_CD , LOCATE_ADDRESS , LOCATE_D_ADDRESS , LOCATE_CN , LOCATE_USE_YN , LOCATE_DEL_YN , REG_ID , REG_DT , UPD_ID , UPD_DT FROM TB_MOIM_LOCATE_INFO WHERE 1=1 AND LOCATE_DEL_YN = 'N'
AND LOCATE_NM LIKE CONCAT('%', #{searchTxt}, '%')
ORDER BY REG_DT DESC LIMIT #{perPage} OFFSET #{startRow}

mapper.insert:
/* AdminMoim_SQL.adminMoimLocateListReg */
INSERT INTO TB_MOIM_LOCATE_INFO (
	  LOCATE_ID
    , LOCATE_NM
    , LOCATE_POST_CD
    , LOCATE_ADDRESS
    , LOCATE_D_ADDRESS
    , LOCATE_CN
    , LOCATE_USE_YN
    , LOCATE_DEL_YN
    , REG_ID
    , REG_DT
    , UPD_ID
    , UPD_DT
) VALUES (
	  (SELECT FN_GET_UNIQUE_KEY())
	, #{locateNm}
	, #{locatePostCd}
	, #{locateAddress}
	, #{locateDAddress}
	, #{locateCn}
	, #{locateUseYn}
	, 'N'
	, #{regId}
	, NOW()
	, #{updId}
	, NOW()
)

mapper.update:
	/* AdminMoim_SQL.adminMoimLocateListUpd */
	UPDATE TB_MOIM_LOCATE_INFO 
		 SET LOCATE_NM				= #{locateNm}
		     , LOCATE_POST_CD		= #{locatePostCd}
		     , LOCATE_ADDRESS		= #{locateAddress}
		     , LOCATE_D_ADDRESS	= #{locateDAddress}
		     , LOCATE_CN				= #{locateCn}
		     , LOCATE_USE_YN		= #{locateUseYn}
		     , UPD_ID					= #{updId}
		     , UPD_DT					= NOW()
     WHERE 1=1
         AND LOCATE_ID = #{locateId}

	/* AdminMoim_SQL.adminMoimLocateListDel */
	UPDATE TB_MOIM_LOCATE_INFO 
		 SET LOCATE_DEL_YN			= 'Y'
     WHERE 1=1
         AND LOCATE_ID = #{locateId}

mapper.select:
/* AdminMoim_SQL.selectAdminMoimList */ SELECT MOIM_ID , MOIM_TITLE , MOIM_DT , MOIM_MAX_CNT , MOIM_DEL_YN , MOIM_LOCATE_ID , MOIM_CN , MOIM_GB , REG_ID , REG_DT , UPD_ID , UPD_DT FROM TB_MOIM_INFO WHERE 1=1 AND MOIM_DEL_YN = 'N'
AND MOIM_TITLE LIKE CONCAT('%', #{searchTxt}, '%')
ORDER BY REG_DT DESC LIMIT #{perPage} OFFSET #{startRow}
